const MAX_INPUT:usize=256;
fn store_le(out:&mut [u8],off:usize,x:i64){out[off..off+8].copy_from_slice(&x.to_le_bytes());}
#[no_mangle]
pub unsafe extern "C" fn unknown_sort(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n>257{return -1;}if n>MAX_INPUT{return -1;}let mut work=[0i64;MAX_INPUT];let mut start=[0i64;MAX_INPUT];let mut end=[0i64;MAX_INPUT];let mut result=[0i64;MAX_INPUT];for i in 0..n{work[i]=*v.add(i);}let mut count=n;let mut used=0;let mut ends=0;while count>1{let(mut min_i,mut max_i)=(0,0);for i in 1..count{if work[i]<work[min_i]{min_i=i;}if work[i]>work[max_i]{max_i=i;}}let(min_v,max_v)=(work[min_i],work[max_i]);start[used]=min_v;used+=1;end[ends]=max_v;ends+=1;for i in min_i..count-1{work[i]=work[i+1];}count-=1;let mut max_pos=0;while max_pos<count&&work[max_pos]!=max_v{max_pos+=1;}if max_pos==count{return -1;}for i in max_pos..count-1{work[i]=work[i+1];}count-=1;}let mut out_n=0;for i in 0..used{result[out_n]=start[i];out_n+=1;}for i in 0..count{result[out_n]=work[i];out_n+=1;}for i in (0..ends).rev(){result[out_n]=end[i];out_n+=1;}let bytes=8*out_n;if out.is_null()||cap<bytes{return -2;}let dst=std::slice::from_raw_parts_mut(out,bytes);for i in 0..out_n{store_le(dst,8*i,result[i]);}bytes as i64}
